"use client";

import Image from "next/image";
import { Search, ChevronDown } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

export function HeroSection() {
  return (
    <section className="border-t border-border bg-white">
      <div className="mx-auto flex max-w-5xl flex-col items-center px-6 py-14">

        {/* Logo */}

        <img
          src="/sidpb/logo.svg"
          alt="Logo"
          width={250}
          height={250}
        />

        {/* Titulo */}
        <p
          className="
            mt-3
            text-center
            text-[22px]
            font-Merriweather
            uppercase
            tracking-[0.08em]
            leading-[1.45]
            text-neutral-500
          "
        >
          <span className="block">
            Sistema de Informação de
          </span>

          <span className="block">
            Doenças Parasitárias no Brasil
          </span>
        </p>


        {/* Search */}

        <div className="mt-10 w-full max-w-4xl">

          <div className="flex">

            <Input
              placeholder="Pesquise por doença, parasito, hospedeiro ou deixe em branco para explorar toda a base..."
              className="
                h-12
                rounded-none
                border-r-0
                text-base
                shadow-none
                focus-visible:ring-0
                focus-visible:border-primary
              "
            />

            <Button
              className="
                h-12
                rounded-none
                px-8
                bg-primary
                hover:bg-primary/90
              "
            >
              <Search className="mr-2 h-4 w-4" />

              Pesquisar
            </Button>

          </div>

          {/* Advanced Search */}

          <button
            className="
              mt-3
              flex
              items-center
              gap-1
              text-sm
              text-muted-foreground
              transition-colors
              hover:text-primary
            "
          >
            Pesquisa Avançada

            <ChevronDown className="h-4 w-4" />
          </button>

        </div>
      </div>
    </section>

    
  );
}